input.sparql:
SELECT ?s ?tsid WHERE {
  ?z a brick:Zone ; rdfs:label "Perimeter_top_ZN_3" .
  ?z ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?tsid .
}

SELECT ?p ?pc ?tsid WHERE {
  ?z a brick:Zone ; rdfs:label "Perimeter_top_ZN_3" .
  ?z brick:hasPoint ?p .
  ?p rdf:type ?pc .
  OPTIONAL { ?p ref:hasExternalReference ?ref . ?ref ref:hasTimeseriesId ?tsid . }
}

SELECT ?p ?pc ?tsid WHERE {
  ?z rdfs:label "Perimeter_top_ZN_3" .
  ?p brick:hasPropertyOf ?z .
  ?p rdf:type ?pc .
  OPTIONAL { ?p ref:hasExternalReference ?ref . ?ref ref:hasTimeseriesId ?tsid . }
}

SELECT ?p ?pc ?tsid WHERE {
  VALUES ?z { <http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z02> }
  { ?z brick:hasPoint ?p } UNION { ?p brick:hasPropertyOf ?z }
  ?p rdf:type ?pc .
  OPTIONAL { ?p ref:hasExternalReference ?ref . ?ref ref:hasTimeseriesId ?tsid . }
}

SELECT ?p ?pc ?tsid ?rl WHERE {
  ?p rdf:type brick:Occupancy_Sensor .
  OPTIONAL { ?p ref:hasExternalReference ?ref . ?ref ref:hasTimeseriesId ?tsid . }
  OPTIONAL { ?p brick:hasPropertyOf ?pl . ?pl rdfs:label ?rl . }
  FILTER(CONTAINS(STRIF(BOUND(?rl)?rl:""), ""))
  FILTER(CONTAINS(STR(?p), "F4"))
}
